// Validate incoming payload is ThingsBoard-compatible flat JSON
// Expected format: {"ts": <epoch_ms>, "values": {"key": value}}

const payload = msg.payload;

if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
    node.error('[telemetry-publish] InvalidPayload: expected object, got ' + typeof payload, msg);
    return null;
}

// Validate 'ts' field
if (typeof payload.ts !== 'number' || !isFinite(payload.ts) || payload.ts <= 0) {
    node.error('[telemetry-publish] InvalidTimestamp: ts must be a positive number (epoch_ms), got ' + payload.ts, msg);
    return null;
}

// Validate 'values' field
if (typeof payload.values !== 'object' || payload.values === null || Array.isArray(payload.values)) {
    node.error('[telemetry-publish] InvalidValues: values must be a flat object', msg);
    return null;
}

if (Object.keys(payload.values).length === 0) {
    node.error('[telemetry-publish] EmptyValues: values object has no keys', msg);
    return null;
}

// Validate no nested objects in values (ThingsBoard requires flat)
for (const [key, val] of Object.entries(payload.values)) {
    if (typeof val === 'object' && val !== null) {
        node.error('[telemetry-publish] NestedValue: key "' + key + '" contains nested object — ThingsBoard requires flat values', msg);
        return null;
    }
}

// Payload is valid — set topic for ThingsBoard and forward
// MQTT-out node handles JSON serialization automatically
msg.topic = 'v1/devices/me/telemetry';

return msg;

// Monitor MQTT-out node connection status changes
// Publish connection state to local Mosquitto for gateway-health flow (Story 1.6)

const status = msg.status;
if (!status || !status.text) {
    return null;
}

const text = status.text.toLowerCase();
let connected = null;

if (text.includes('connected') && !text.includes('disconnect')) {
    connected = true;
} else if (text.includes('disconnect') || text.includes('error') || text.includes('close')) {
    connected = false;
}

if (connected === null) {
    return null;
}

// Publish to local Mosquitto for gateway-health flow consumption
msg.payload = JSON.stringify({
    cloud_connected: connected,
    ts: Date.now()
});
msg.topic = 'nexus/internal/cloud-connection-status';

if (connected) {
    node.status({ fill: 'green', shape: 'dot', text: 'cloud connected' });
} else {
    node.status({ fill: 'red', shape: 'ring', text: 'cloud disconnected' });
    node.warn('[telemetry-publish] CloudDisconnected: ThingsBoard MQTT connection lost');
}

return msg;

// Format error message for logging
const errorSource = msg.error ? msg.error.source : {};
const errorMsg = msg.error ? msg.error.message : 'Unknown error';
const nodeName = errorSource.name || errorSource.id || 'unknown';

node.warn('[telemetry-publish] ' + nodeName + ': ' + errorMsg);

// Prepare error status for gateway health (consumed by gateway-health flow in Story 1.6)
msg.payload = JSON.stringify({
    ts: Date.now(),
    values: {
        tp_error_count: 1,
        tp_last_error: errorMsg.substring(0, 200)
    }
});
msg.topic = 'nexus/internal/telemetry-publish-errors';

return msg;
